CREATE TYPE "SandboxStatus" AS ENUM ('creating','ready','stopping','stopped','failed','deleted');
CREATE TYPE "CommandStatus" AS ENUM ('running','succeeded','failed','timed_out','cancelled');
CREATE TYPE "SandboxEventActor" AS ENUM ('api','provisioner','runtime','cleanup');
CREATE TYPE "OutputStream" AS ENUM ('stdout','stderr');
CREATE TABLE "sandboxes" ("id" TEXT NOT NULL,"task_id" TEXT,"status" "SandboxStatus" NOT NULL,"container_id" TEXT,"container_name" TEXT NOT NULL,"image" TEXT NOT NULL,"workspace_path" TEXT NOT NULL,"fixture_repo_path" TEXT NOT NULL,"next_event_sequence" INTEGER NOT NULL DEFAULT 1,"failure_code" TEXT,"failure_message" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ready_at" TIMESTAMP(3),"stopping_at" TIMESTAMP(3),"stopped_at" TIMESTAMP(3),"failed_at" TIMESTAMP(3),"deleted_at" TIMESTAMP(3),CONSTRAINT "sandboxes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "commands" ("id" TEXT NOT NULL,"sandbox_id" TEXT NOT NULL,"status" "CommandStatus" NOT NULL,"command" TEXT NOT NULL,"cwd" TEXT NOT NULL,"env" JSONB,"timeout_ms" INTEGER NOT NULL,"exit_code" INTEGER,"output_bytes" INTEGER NOT NULL DEFAULT 0,"output_truncated" BOOLEAN NOT NULL DEFAULT false,"failure_code" TEXT,"failure_message" TEXT,"started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "commands_pkey" PRIMARY KEY ("id"));
CREATE TABLE "sandbox_events" ("id" TEXT NOT NULL,"sandbox_id" TEXT NOT NULL,"command_id" TEXT,"sequence" INTEGER NOT NULL,"type" TEXT NOT NULL,"actor" "SandboxEventActor" NOT NULL,"correlation_id" TEXT,"payload" JSONB NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "sandbox_events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sandboxes_container_name_key" ON "sandboxes"("container_name");
CREATE UNIQUE INDEX "sandbox_events_sandbox_id_sequence_key" ON "sandbox_events"("sandbox_id","sequence");
CREATE UNIQUE INDEX "commands_one_running_per_sandbox" ON "commands"("sandbox_id") WHERE "status" = 'running';
CREATE INDEX "sandboxes_status_created_at_idx" ON "sandboxes"("status","created_at"); CREATE INDEX "sandboxes_created_at_idx" ON "sandboxes"("created_at");
CREATE INDEX "commands_sandbox_id_created_at_idx" ON "commands"("sandbox_id","created_at"); CREATE INDEX "commands_sandbox_id_status_idx" ON "commands"("sandbox_id","status");
CREATE INDEX "sandbox_events_sandbox_id_sequence_idx" ON "sandbox_events"("sandbox_id","sequence"); CREATE INDEX "sandbox_events_sandbox_id_created_at_idx" ON "sandbox_events"("sandbox_id","created_at"); CREATE INDEX "sandbox_events_command_id_sequence_idx" ON "sandbox_events"("command_id","sequence");
ALTER TABLE "sandboxes" ADD CONSTRAINT "sandboxes_next_event_sequence_positive" CHECK ("next_event_sequence" > 0); ALTER TABLE "commands" ADD CONSTRAINT "commands_timeout_positive" CHECK ("timeout_ms" > 0); ALTER TABLE "commands" ADD CONSTRAINT "commands_output_bytes_nonnegative" CHECK ("output_bytes" >= 0);
ALTER TABLE "commands" ADD CONSTRAINT "commands_command_nonempty" CHECK (length(trim("command")) > 0);
ALTER TABLE "commands" ADD CONSTRAINT "commands_sandbox_id_fkey" FOREIGN KEY ("sandbox_id") REFERENCES "sandboxes"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "sandbox_events" ADD CONSTRAINT "sandbox_events_sandbox_id_fkey" FOREIGN KEY ("sandbox_id") REFERENCES "sandboxes"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "sandbox_events" ADD CONSTRAINT "sandbox_events_command_id_fkey" FOREIGN KEY ("command_id") REFERENCES "commands"("id") ON DELETE SET NULL ON UPDATE CASCADE;
